-- Dominio: Contenido y preguntas
-- Banco de preguntas de selección múltiple para Lengua y Literatura,
-- Currículum Regular, 2° Medio (D.S. 614/2013), 4 ejes: Lectura, Escritura,
-- Comunicación Oral, Investigación. 4 preguntas por cada uno de los 17
-- objetivos de aprendizaje ya cargados en
-- supabase/seed/0015_curriculum_lenguaje_regular_7basico_2medio.sql
-- (unit_id + level_id + short_name, NUNCA ids hardcodeados).
--
-- Mismo criterio editorial, de validación, de formato y de idempotencia
-- documentado en supabase/seed/0064_question_bank_lenguaje_regular_
-- 7basico.sql -- no se repite aquí el detalle completo. Resumen:
--   - `review_status = 'borrador'`, `validation_status =
--     'ai_generated_review_required'`, `is_active = true`,
--     `source_type = 'validapp_original'`, `framework_id` NULL.
--   - NINGUNA pregunta de este archivo se muestra a estudiantes hasta
--     revisión y aprobación humana individual (ver 0023, 0064 y
--     `lib/data/essays.ts`).
--   - Fragmentos citados dentro de los enunciados son creaciones originales
--     de ValidApp con fines pedagógicos, no citas de obras reales.
--   - `content_hash` queda NULL (se calcula en TypeScript, no en SQL); este
--     archivo se validó localmente con el mismo script Node ad-hoc que
--     replica `validateQuestion`/`computeContentHash`/`textSimilarity`.
--   - Idempotencia con `where not exists (...)` sobre
--     `learning_objective_id` + `prompt`. Seed SOLO local.

-- ============================================================================
-- EJE: LECTURA — 2° MEDIO (5 objetivos x 4 preguntas = 20)
-- ============================================================================
insert into public.questions (
  subject_id, level_id, lesson_id, prompt, choices, correct_index, explanation,
  learning_objective_id, difficulty, question_type, points, estimated_seconds,
  review_status, validation_status, is_active, source_type, generated_by, generated_at
)
select
  (select id from public.subjects where name = 'Lengua Castellana y Comunicación'),
  lv.id, null, v.prompt, v.choices::jsonb, v.correct_index, v.explanation,
  lo.id, v.difficulty, 'seleccion_multiple', 1, v.estimated_seconds,
  'borrador', 'ai_generated_review_required', true, 'validapp_original',
  'claude-sonnet-5 (validapp-assessments)', now()
from (values
  ('Obras de distintos movimientos o períodos', '¿Qué permite identificar el movimiento o período literario al que pertenece una obra?', '["Únicamente la fecha de nacimiento del autor","Sus características temáticas, estilísticas y el contexto histórico-cultural en que se inserta","El precio actual del libro en librerías","El idioma original en que fue escrita"]', 1, 'Un movimiento literario se identifica por sus rasgos temáticos y estilísticos, además del contexto histórico-cultural en que se inserta la obra.', 'inicial', 60),
  ('Obras de distintos movimientos o períodos', 'Una obra del Romanticismo exalta la subjetividad y las emociones intensas del yo poético, mientras una obra realista se centra en la observación objetiva de la sociedad. ¿Qué permite explicar esta diferencia?', '["Que una de las dos corrientes literarias es incorrecta","Que cada movimiento literario tiene rasgos estéticos y temáticos propios de su época","Que ambas obras pertenecen exactamente al mismo movimiento","Que la diferencia se debe únicamente al idioma en que fueron escritas"]', 1, 'Cada movimiento literario desarrolla rasgos estéticos y temáticos propios, vinculados a la sensibilidad y el contexto de su época.', 'intermedia', 90),
  ('Obras de distintos movimientos o períodos', '¿Cuál de las siguientes NO es una característica útil para comparar obras de distintos movimientos literarios?', '["Los temas y preocupaciones predominantes de cada época","Los recursos estilísticos característicos de cada movimiento","El número de ejemplares vendidos de cada obra actualmente","La visión de mundo asociada a cada corriente literaria"]', 2, 'El número de ejemplares vendidos actualmente es un dato comercial, no un criterio literario para comparar movimientos o períodos.', 'intermedia', 90),
  ('Obras de distintos movimientos o períodos', 'Un poema vanguardista rompe con la métrica tradicional y experimenta con la disposición gráfica de las palabras en la página. ¿Qué relación existe entre esta forma y el movimiento literario al que pertenece?', '["Ninguna relación, la forma es independiente del movimiento literario","La ruptura formal expresa la búsqueda de innovación característica de las vanguardias","Es un error de imprenta sin ninguna intención estética","Todos los movimientos literarios comparten exactamente la misma forma"]', 1, 'La experimentación formal es característica de las vanguardias, que buscan romper con las convenciones literarias previas.', 'avanzada', 120),

  ('Interpretación de textos filosóficos y ensayísticos', '¿Qué habilidad es fundamental para interpretar críticamente un texto filosófico o ensayístico?', '["Memorizar el texto palabra por palabra","Identificar la tesis del autor y reconstruir el razonamiento que la sustenta","Evaluar únicamente la extensión del texto","Aceptar la tesis sin ningún análisis"]', 1, 'Interpretar críticamente un texto filosófico requiere identificar su tesis y reconstruir el razonamiento que la sustenta.', 'inicial', 60),
  ('Interpretación de textos filosóficos y ensayísticos', 'Un ensayo filosófico plantea que la libertad humana está limitada por las condiciones sociales en que vive cada persona, desarrollando esta idea a través de varios ejemplos. ¿Qué se espera del lector para interpretar correctamente este texto?', '["Rechazar el ensayo sin ningún análisis","Seguir el desarrollo argumentativo y relacionar los ejemplos con la tesis central","Memorizar únicamente los ejemplos sin relacionarlos con ninguna idea","Ignorar la tesis y quedarse solo con los ejemplos"]', 1, 'Interpretar el texto requiere seguir el desarrollo argumentativo y comprender cómo los ejemplos se relacionan con la tesis central.', 'intermedia', 90),
  ('Interpretación de textos filosóficos y ensayísticos', '¿Cuál de las siguientes estrategias NO ayuda a interpretar un texto filosófico complejo?', '["Identificar los conceptos clave que utiliza el autor","Relacionar el texto con el contexto filosófico o histórico en que fue escrito","Leer de forma superficial, saltándose los párrafos más abstractos","Reconstruir la progresión lógica de los argumentos presentados"]', 2, 'Saltarse los párrafos más abstractos impide comprender adecuadamente el razonamiento completo de un texto filosófico complejo.', 'intermedia', 90),
  ('Interpretación de textos filosóficos y ensayísticos', 'Un ensayo filosófico utiliza conceptos abstractos como "libertad" y "determinismo" sin definirlos explícitamente, asumiendo que el lector los conoce. ¿Qué estrategia de interpretación es más adecuada en este caso?', '["Ignorar el texto por considerarlo incomprensible","Investigar el significado de esos conceptos en el contexto filosófico del autor para interpretar correctamente el texto","Inventar una definición personal sin ninguna base","Asumir que los conceptos no tienen ningún significado relevante"]', 1, 'Investigar el significado de los conceptos clave dentro del contexto filosófico del autor permite una interpretación más precisa del texto.', 'avanzada', 120),

  ('Recursos retóricos en discursos públicos', '¿Qué es un recurso retórico en un discurso público?', '["Un error de redacción que debilita el discurso","Una estrategia del lenguaje utilizada para persuadir o convencer a la audiencia","Un dato estadístico presentado sin ninguna interpretación","Un tipo de letra usado en las diapositivas del discurso"]', 1, 'Un recurso retórico es una estrategia del lenguaje utilizada intencionadamente para persuadir o convencer a una audiencia.', 'inicial', 60),
  ('Recursos retóricos en discursos públicos', 'Un orador repite tres veces la misma estructura de oración para enfatizar una idea central de su discurso ("queremos justicia, queremos igualdad, queremos dignidad"). ¿Qué recurso retórico está utilizando?', '["Antítesis","Anáfora, repetición de una estructura al inicio de frases sucesivas","Hipérbole","Ironía"]', 1, 'La repetición de una misma estructura al inicio de frases sucesivas corresponde a la anáfora, un recurso retórico usado para enfatizar una idea.', 'intermedia', 90),
  ('Recursos retóricos en discursos públicos', '¿Cuál de las siguientes opciones NO corresponde a un recurso retórico utilizado en discursos públicos?', '["La pregunta retórica, para hacer reflexionar a la audiencia","La anáfora, para enfatizar una idea mediante la repetición","El uso de una fuente tipográfica llamativa en un afiche","La apelación a las emociones del público de forma pertinente"]', 2, 'El diseño tipográfico de un afiche es un recurso gráfico, no un recurso retórico del lenguaje propio de un discurso oral.', 'intermedia', 90),
  ('Recursos retóricos en discursos públicos', 'Un discurso político usa la pregunta retórica "¿acaso no merecemos un futuro mejor?" seguida de varios ejemplos concretos de problemas sociales. ¿Qué efecto busca lograr esta combinación de recursos?', '["Ningún efecto relevante en la audiencia","Involucrar emocionalmente a la audiencia y luego respaldar la idea con evidencia concreta","Confundir a la audiencia con preguntas sin respuesta","Reemplazar la necesidad de presentar argumentos válidos"]', 1, 'La combinación de una pregunta retórica con ejemplos concretos busca involucrar emocionalmente a la audiencia y luego respaldar la idea con evidencia.', 'avanzada', 120),

  ('Argumentación y falacias en un texto', '¿Qué es una falacia en el contexto de la argumentación?', '["Un argumento que parece válido pero contiene un error de razonamiento","Un sinónimo de argumento válido y bien fundamentado","Un dato estadístico verificado","Una cita textual de una fuente confiable"]', 0, 'Una falacia es un argumento que aparenta ser válido, pero contiene un error de razonamiento que lo invalida lógicamente.', 'inicial', 60),
  ('Argumentación y falacias en un texto', 'Un texto afirma: "Si permitimos que los estudiantes usen calculadora en las pruebas, pronto no sabrán ni sumar, y luego la sociedad entera perderá la capacidad de pensar". ¿Qué falacia se identifica en este razonamiento?', '["Ad hominem","Pendiente resbaladiza, al encadenar consecuencias exageradas sin evidencia","Apelación a la autoridad","Falso dilema"]', 1, 'Encadenar consecuencias cada vez más extremas sin evidencia que las respalde es característico de la falacia de pendiente resbaladiza.', 'intermedia', 90),
  ('Argumentación y falacias en un texto', '¿Cuál de las siguientes opciones NO corresponde a una falacia argumentativa?', '["Atacar a la persona en vez de responder a su argumento (ad hominem)","Presentar solo dos opciones cuando existen más alternativas (falso dilema)","Sustentar una tesis con evidencia pertinente y verificable","Generalizar a partir de un caso aislado y poco representativo"]', 2, 'Sustentar una tesis con evidencia pertinente y verificable es propio de un argumento válido, no de una falacia.', 'intermedia', 90),
  ('Argumentación y falacias en un texto', 'Un texto sostiene que una teoría científica es falsa "porque un famoso actor dijo en una entrevista que no cree en ella". ¿Qué falacia se identifica en este argumento?', '["Apelación a la autoridad, al citar una opinión no especializada como si fuera prueba suficiente","Pendiente resbaladiza","Falso dilema","Generalización apresurada"]', 0, 'Citar la opinión de una persona sin experticia en el tema como si fuera prueba suficiente corresponde a la falacia de apelación a una autoridad no pertinente.', 'avanzada', 120),

  ('Interpretación personal fundamentada de una obra', '¿Qué requiere una interpretación personal fundamentada de una obra literaria completa?', '["Repetir la opinión de un crítico literario sin ningún análisis propio","Elaborar una lectura propia de la obra, apoyada en evidencia textual concreta","Evitar cualquier relación con el texto original","Basarse únicamente en el gusto personal, sin ninguna evidencia"]', 1, 'Una interpretación personal fundamentada requiere elaborar una lectura propia, respaldada en evidencia textual concreta.', 'inicial', 60),
  ('Interpretación personal fundamentada de una obra', 'Un estudiante interpreta que el protagonista de una novela representa la lucha entre el deber y el deseo personal, citando escenas específicas donde el personaje enfrenta este dilema. ¿Qué característica cumple esta interpretación?', '["Es una interpretación fundamentada, apoyada en evidencia textual concreta","Es una opinión sin ninguna relación con la obra","Es una interpretación inválida por ser una idea personal","Es una copia de la contratapa del libro"]', 0, 'Citar escenas concretas de la novela para sustentar una interpretación es lo que la hace una interpretación fundamentada.', 'intermedia', 90),
  ('Interpretación personal fundamentada de una obra', '¿Cuál de las siguientes NO es una interpretación personal fundamentada de una obra?', '["Una lectura que relaciona el desenlace de la obra con su tema central, citando evidencia textual","Una opinión que afirma que la obra \"es aburrida\" sin ninguna relación con el texto","Una interpretación que analiza el simbolismo de un objeto recurrente en la obra","Una lectura que conecta el conflicto de un personaje con la visión de mundo de la obra"]', 1, 'Afirmar que una obra "es aburrida" sin ninguna relación con elementos concretos del texto no constituye una interpretación fundamentada.', 'intermedia', 90),
  ('Interpretación personal fundamentada de una obra', 'Dos lectores de una misma novela llegan a interpretaciones distintas sobre el final abierto de la obra, ambas respaldadas con evidencia textual coherente. ¿Qué se puede concluir sobre esta situación?', '["Solo una interpretación puede ser correcta","Una obra puede admitir más de una interpretación válida si cada una se fundamenta adecuadamente en el texto","El autor de la obra cometió un error al dejar el final abierto","Las interpretaciones sin importar su fundamento son igualmente válidas"]', 1, 'Un texto literario puede admitir más de una interpretación legítima, siempre que cada una se fundamente adecuadamente en la evidencia textual.', 'avanzada', 120)
) as v(short_name, prompt, choices, correct_index, explanation, difficulty, estimated_seconds)
join public.learning_objectives lo
  on lo.short_name = v.short_name
  and lo.unit_id = (
    select id from public.units
    where strand_id = (select id from public.strands where subject_id = (select id from public.subjects where name = 'Lengua Castellana y Comunicación') and name = 'Lectura')
      and name = 'Lectura — 2° Medio'
  )
cross join (select id from public.levels where code = 'regular_2_medio') as lv
where lo.level_id = lv.id
  and not exists (
    select 1 from public.questions q2
    where q2.learning_objective_id = lo.id and q2.prompt = v.prompt
  );

-- ============================================================================
-- EJE: ESCRITURA — 2° MEDIO (4 objetivos x 4 preguntas = 16)
-- ============================================================================
insert into public.questions (
  subject_id, level_id, lesson_id, prompt, choices, correct_index, explanation,
  learning_objective_id, difficulty, question_type, points, estimated_seconds,
  review_status, validation_status, is_active, source_type, generated_by, generated_at
)
select
  (select id from public.subjects where name = 'Lengua Castellana y Comunicación'),
  lv.id, null, v.prompt, v.choices::jsonb, v.correct_index, v.explanation,
  lo.id, v.difficulty, 'seleccion_multiple', 1, v.estimated_seconds,
  'borrador', 'ai_generated_review_required', true, 'validapp_original',
  'claude-sonnet-5 (validapp-assessments)', now()
from (values
  ('Ensayos argumentativos con contraargumentación', '¿Qué función cumple la contraargumentación dentro de un ensayo argumentativo?', '["Debilitar la tesis del propio ensayo sin ningún propósito","Anticiparse a posibles objeciones y refutarlas, fortaleciendo la tesis central","Reemplazar por completo la tesis planteada al inicio","Confundir al lector con ideas contrarias sin ninguna resolución"]', 1, 'La contraargumentación permite anticiparse a posibles objeciones y refutarlas, lo que fortalece la tesis central del ensayo.', 'inicial', 60),
  ('Ensayos argumentativos con contraargumentación', 'Un estudiante escribe un ensayo defendiendo la reducción de la jornada laboral, y en un párrafo reconoce que esta medida podría afectar la productividad de algunas empresas, para luego explicar por qué los beneficios superan ese riesgo. ¿Qué logra con este recurso?', '["Debilitar completamente su propia tesis","Fortalecer su argumentación al mostrar que consideró y respondió a una objeción válida","Cambiar por completo el tema de su ensayo","Hacer el ensayo más confuso para el lector"]', 1, 'Reconocer y responder a una objeción válida fortalece la argumentación, mostrando un análisis más completo del tema.', 'intermedia', 90),
  ('Ensayos argumentativos con contraargumentación', '¿Cuál de las siguientes opciones NO corresponde a una buena contraargumentación dentro de un ensayo?', '["Reconocer una objeción válida a la propia tesis","Responder a la objeción con argumentos o evidencia","Ignorar cualquier objeción posible a la propia tesis","Mantener la coherencia con la tesis general del ensayo al responder la objeción"]', 2, 'Ignorar cualquier objeción posible contradice el propósito de la contraargumentación, que busca reconocerla y responderla.', 'intermedia', 90),
  ('Ensayos argumentativos con contraargumentación', 'Un estudiante incluye una contraargumentación en su ensayo, pero no logra refutarla adecuadamente, dejando la objeción sin responder. ¿Qué efecto tiene esto en su argumentación?', '["Ningún efecto, basta con mencionar la objeción","Puede debilitar la solidez de su tesis, al no resolver la objeción planteada","Fortalece automáticamente su argumentación","Elimina la necesidad de tener una tesis clara"]', 1, 'Mencionar una objeción sin refutarla adecuadamente puede debilitar la solidez de la tesis, en vez de fortalecerla.', 'avanzada', 120),

  ('Textos literarios con intención estética definida', '¿Qué significa que un texto literario tenga una "intención estética definida"?', '["Que el autor busca lograr un efecto artístico o expresivo específico mediante recursos literarios","Que el texto no tiene ningún propósito comunicativo","Que el texto debe ser exactamente igual a otros textos del mismo género","Que el autor escribe sin ninguna planificación previa"]', 0, 'Una intención estética definida implica que el autor busca lograr, de forma deliberada, un efecto artístico o expresivo específico.', 'inicial', 60),
  ('Textos literarios con intención estética definida', 'Un estudiante escribe un poema utilizando repeticiones y un ritmo marcado para transmitir una sensación de urgencia y angustia. ¿Qué demuestra esta decisión?', '["Que el poema no tiene ninguna intención estética","Una intención estética definida, al usar recursos formales para lograr un efecto expresivo específico","Un error de redacción que debería corregirse","Que el poema carece de cualquier sentido"]', 1, 'Usar recursos formales (repeticiones, ritmo) de manera intencionada para lograr un efecto expresivo demuestra una intención estética definida.', 'intermedia', 90),
  ('Textos literarios con intención estética definida', '¿Cuál de las siguientes opciones NO refleja una intención estética definida en un texto literario?', '["Elegir un tipo de narrador que aporte un efecto particular a la historia","Usar un ritmo y sonoridad particulares en un poema para reforzar su sentido","Escribir sin ninguna consideración sobre el efecto que el texto genera en el lector","Seleccionar cuidadosamente las palabras según el tono que se busca transmitir"]', 2, 'Escribir sin considerar el efecto en el lector es contrario a tener una intención estética definida, que implica decisiones deliberadas.', 'intermedia', 90),
  ('Textos literarios con intención estética definida', 'Un estudiante escribe un cuento breve utilizando oraciones cada vez más cortas hacia el final, para generar una sensación de tensión creciente. ¿Qué relación existe entre esta decisión formal y la intención estética del texto?', '["Ninguna relación entre la forma y el efecto buscado","La forma (oraciones cada vez más cortas) refuerza intencionadamente el efecto de tensión buscado","Es un error de redacción que afecta negativamente el cuento","Todos los cuentos deben usar exactamente esta misma estructura"]', 1, 'La forma elegida (oraciones cada vez más cortas) refuerza de manera intencionada el efecto de tensión creciente buscado en el cuento.', 'avanzada', 120),

  ('Revisión aplicando criterios de estilo y registro', 'Al revisar un texto aplicando criterios de estilo y registro, ¿qué se debe evaluar principalmente?', '["Únicamente la ortografía de las palabras","Que el lenguaje utilizado sea adecuado al propósito, género y audiencia del texto","La cantidad de páginas que tiene el texto","El tipo de letra utilizado al imprimir el texto"]', 1, 'Revisar el estilo y registro implica evaluar que el lenguaje sea adecuado al propósito, género y audiencia del texto.', 'inicial', 60),
  ('Revisión aplicando criterios de estilo y registro', 'Un estudiante revisa su ensayo académico y reemplaza expresiones coloquiales por un vocabulario más formal y preciso. ¿Qué criterio de revisión está aplicando?', '["Un criterio de extensión del texto","Un criterio de estilo y registro, adecuando el lenguaje al género académico","Un criterio exclusivamente ortográfico","Un criterio relacionado con el diseño gráfico del texto"]', 1, 'Adecuar el vocabulario coloquial a uno formal y preciso corresponde a un criterio de estilo y registro, apropiado al género académico.', 'intermedia', 90),
  ('Revisión aplicando criterios de estilo y registro', '¿Cuál de las siguientes acciones NO corresponde a revisar el estilo y registro de un texto?', '["Verificar que el vocabulario sea adecuado al género textual","Ajustar el tono del texto según la audiencia a la que se dirige","Contar el número total de palabras del texto sin evaluar su adecuación","Revisar que el registro (formal o informal) sea coherente en todo el texto"]', 2, 'Contar el número de palabras sin evaluar su adecuación no corresponde a revisar el estilo o el registro de un texto.', 'intermedia', 90),
  ('Revisión aplicando criterios de estilo y registro', 'Un estudiante revisa un discurso que debe presentar ante autoridades del colegio y nota que mezcla expresiones muy formales con frases coloquiales. ¿Qué debería corregir?', '["Nada, la mezcla de registros no afecta la comunicación en este contexto","Unificar el registro del discurso, manteniendo un tono formal coherente para la audiencia","Eliminar por completo el contenido formal del discurso","Aumentar aún más las expresiones coloquiales"]', 1, 'Ante una audiencia formal, conviene unificar el registro del discurso, manteniendo un tono formal coherente en todo el texto.', 'avanzada', 120),

  ('Uso autónomo y correcto de convenciones', '¿Qué significa aplicar de manera "autónoma" las convenciones de la lengua escrita?', '["Aplicarlas correctamente sin depender de la corrección constante de otra persona","Ignorar las normas de ortografía y gramática","Aplicarlas solo cuando un profesor lo supervisa directamente","Inventar nuevas reglas ortográficas propias"]', 0, 'Aplicar las convenciones de manera autónoma implica hacerlo correctamente por cuenta propia, sin depender de la corrección constante de otra persona.', 'inicial', 60),
  ('Uso autónomo y correcto de convenciones', 'Un estudiante revisa y corrige su propio ensayo, identificando y solucionando errores de puntuación, concordancia y ortografía sin ayuda externa. ¿Qué demuestra esta acción?', '["Una dependencia total de la corrección de otras personas","Un uso autónomo y correcto de las convenciones de la lengua escrita","Que el estudiante no comprende las reglas ortográficas","Que la revisión de un texto no aporta ningún beneficio"]', 1, 'Corregir por cuenta propia errores de puntuación, concordancia y ortografía demuestra un uso autónomo y correcto de las convenciones.', 'intermedia', 90),
  ('Uso autónomo y correcto de convenciones', '¿Cuál de las siguientes situaciones NO refleja un uso autónomo de las convenciones de la lengua escrita?', '["Revisar y corregir el propio texto antes de entregarlo","Aplicar las reglas de tildación sin necesidad de que otra persona las señale","Depender de que otra persona corrija cada error del texto sin revisión propia","Reconocer y corregir errores de concordancia en las propias oraciones"]', 2, 'Depender siempre de que otra persona corrija los errores contradice la idea de un uso autónomo de las convenciones de la lengua escrita.', 'intermedia', 90),
  ('Uso autónomo y correcto de convenciones', 'Un estudiante domina con autonomía las convenciones básicas de ortografía y puntuación, pero comete errores frecuentes en el uso de conectores complejos entre ideas. ¿Qué debería seguir desarrollando?', '["Nada, ya domina completamente todas las convenciones de la lengua escrita","El uso autónomo y correcto de conectores más complejos para relacionar ideas","Dejar de revisar su ortografía básica","Evitar el uso de cualquier conector en sus textos"]', 1, 'Seguir desarrollando el uso autónomo de conectores complejos es el siguiente paso natural tras dominar las convenciones básicas.', 'avanzada', 120)
) as v(short_name, prompt, choices, correct_index, explanation, difficulty, estimated_seconds)
join public.learning_objectives lo
  on lo.short_name = v.short_name
  and lo.unit_id = (
    select id from public.units
    where strand_id = (select id from public.strands where subject_id = (select id from public.subjects where name = 'Lengua Castellana y Comunicación') and name = 'Escritura')
      and name = 'Escritura — 2° Medio'
  )
cross join (select id from public.levels where code = 'regular_2_medio') as lv
where lo.level_id = lv.id
  and not exists (
    select 1 from public.questions q2
    where q2.learning_objective_id = lo.id and q2.prompt = v.prompt
  );

-- ============================================================================
-- EJE: COMUNICACIÓN ORAL — 2° MEDIO (4 objetivos x 4 preguntas = 16)
-- ============================================================================
insert into public.questions (
  subject_id, level_id, lesson_id, prompt, choices, correct_index, explanation,
  learning_objective_id, difficulty, question_type, points, estimated_seconds,
  review_status, validation_status, is_active, source_type, generated_by, generated_at
)
select
  (select id from public.subjects where name = 'Lengua Castellana y Comunicación'),
  lv.id, null, v.prompt, v.choices::jsonb, v.correct_index, v.explanation,
  lo.id, v.difficulty, 'seleccion_multiple', 1, v.estimated_seconds,
  'borrador', 'ai_generated_review_required', true, 'validapp_original',
  'claude-sonnet-5 (validapp-assessments)', now()
from (values
  ('Discurso persuasivo sobre un tema controversial', '¿Qué característica distingue a un discurso persuasivo sobre un tema controversial?', '["Presenta un tema sin ninguna postura definida","Defiende una postura sobre un tema que genera opiniones divididas en la sociedad","Evita cualquier tipo de argumento o evidencia","Solo puede tratar temas sin ninguna relevancia social"]', 1, 'Un discurso persuasivo sobre un tema controversial defiende una postura clara sobre un asunto que genera opiniones divididas en la sociedad.', 'inicial', 60),
  ('Discurso persuasivo sobre un tema controversial', 'Un estudiante desarrolla un discurso persuasivo sobre la regulación de la inteligencia artificial, presentando argumentos y reconociendo las posturas contrarias antes de refutarlas. ¿Qué logra con esta estrategia?', '["Debilitar completamente su discurso","Fortalecer su discurso al mostrar un análisis más completo del tema controversial","Confundir a la audiencia sin ningún propósito","Evitar tener una postura clara sobre el tema"]', 1, 'Reconocer y refutar posturas contrarias fortalece el discurso, mostrando un análisis más completo del tema controversial.', 'intermedia', 90),
  ('Discurso persuasivo sobre un tema controversial', '¿Cuál de las siguientes estrategias NO es adecuada al desarrollar un discurso persuasivo sobre un tema controversial?', '["Presentar evidencia que respalde la postura defendida","Reconocer la existencia de posturas distintas sobre el tema","Descalificar a quienes piensan diferente sin responder a sus argumentos","Mantener un tono respetuoso hacia posturas contrarias"]', 2, 'Descalificar a quienes piensan diferente sin responder a sus argumentos contradice una argumentación rigurosa y respetuosa.', 'intermedia', 90),
  ('Discurso persuasivo sobre un tema controversial', 'Un estudiante presenta un discurso persuasivo sobre un tema controversial, pero omite por completo cualquier mención a las posturas contrarias existentes. ¿Qué riesgo tiene esta estrategia?', '["Ninguno, mencionar otras posturas siempre debilita un discurso","Puede parecer un análisis incompleto o poco riguroso del tema ante una audiencia informada","Fortalece automáticamente la persuasión del discurso","Es la única forma correcta de abordar un tema controversial"]', 1, 'Omitir por completo las posturas contrarias puede hacer que el discurso parezca incompleto o poco riguroso ante una audiencia informada.', 'avanzada', 120),

  ('Panel de discusión sintetizando posturas', 'En un panel de discusión, ¿qué habilidad es importante para sintetizar las posturas presentadas?', '["Repetir textualmente lo dicho por cada participante sin ningún análisis","Identificar los puntos en común y las diferencias entre las distintas posturas expuestas","Ignorar las posturas de los demás participantes","Imponer la propia postura sin considerar las demás"]', 1, 'Sintetizar un panel de discusión implica identificar los puntos en común y las diferencias entre las posturas expuestas.', 'inicial', 60),
  ('Panel de discusión sintetizando posturas', 'Al finalizar un panel sobre el uso de redes sociales en adolescentes, un participante resume: "todos coincidimos en que existe un riesgo, aunque discrepamos sobre cómo regularlo". ¿Qué logra esta intervención?', '["Confundir aún más a la audiencia sobre el tema tratado","Sintetizar de forma clara los puntos de acuerdo y desacuerdo del panel","Imponer una única postura como la correcta","Repetir literalmente todo lo dicho por cada participante"]', 1, 'Esta intervención sintetiza claramente los puntos de acuerdo (existencia del riesgo) y de desacuerdo (cómo regularlo) del panel.', 'intermedia', 90),
  ('Panel de discusión sintetizando posturas', '¿Cuál de las siguientes acciones NO corresponde a sintetizar adecuadamente las posturas de un panel de discusión?', '["Identificar los acuerdos y desacuerdos entre los participantes","Resumir de forma clara y objetiva las ideas centrales expuestas","Presentar únicamente la postura propia como la única válida","Reconocer los matices dentro de posturas aparentemente similares"]', 2, 'Presentar solo la propia postura como la única válida contradice el propósito de sintetizar de forma objetiva las distintas posturas de un panel.', 'intermedia', 90),
  ('Panel de discusión sintetizando posturas', 'En un panel con cuatro posturas distintas sobre un tema, un participante logra identificar que dos de ellas comparten un supuesto común, aunque lleguen a conclusiones distintas. ¿Qué habilidad demuestra al hacer esta observación?', '["Ninguna habilidad relevante para la discusión","Una capacidad de análisis y síntesis que permite comprender matices entre posturas aparentemente distintas","Una confusión sobre las posturas presentadas","Una simplificación excesiva del debate"]', 1, 'Identificar un supuesto común entre posturas que llegan a conclusiones distintas demuestra una capacidad de análisis y síntesis profunda.', 'avanzada', 120),

  ('Análisis crítico de argumentación en medios masivos', '¿Qué implica analizar críticamente la argumentación presente en medios de comunicación masivos?', '["Aceptar sin cuestionamiento cualquier argumento presentado","Evaluar la solidez de los argumentos, las fuentes citadas y las posibles intenciones del medio","Ignorar por completo la información entregada por los medios","Evaluar únicamente la duración de un programa o noticiero"]', 1, 'Analizar críticamente la argumentación en medios implica evaluar la solidez de los argumentos, las fuentes citadas y las posibles intenciones del medio.', 'inicial', 60),
  ('Análisis crítico de argumentación en medios masivos', 'Un programa de televisión presenta una noticia con un titular alarmante, pero al analizar el contenido no se citan fuentes ni datos concretos. ¿Qué debilidad se identifica desde un análisis crítico?', '["Ninguna, todos los titulares alarmantes están bien fundamentados","La falta de fuentes o datos que respalden la información presentada","Que la noticia es completamente objetiva","Que el titular alarmante garantiza la veracidad de la noticia"]', 1, 'La falta de fuentes o datos concretos que respalden la información es una debilidad identificable mediante un análisis crítico.', 'intermedia', 90),
  ('Análisis crítico de argumentación en medios masivos', '¿Cuál de las siguientes estrategias NO corresponde a un análisis crítico de la argumentación en medios masivos?', '["Verificar si las afirmaciones del medio pueden contrastarse con otras fuentes","Identificar la intención o postura del medio de comunicación","Aceptar la información porque el medio tiene muchos seguidores en redes sociales","Evaluar si los argumentos presentados están bien fundamentados"]', 2, 'La popularidad de un medio en redes sociales no garantiza la solidez de su argumentación ni la veracidad de su información.', 'intermedia', 90),
  ('Análisis crítico de argumentación en medios masivos', 'Dos medios de comunicación presentan la misma noticia con datos distintos, y ninguno cita explícitamente sus fuentes. ¿Qué estrategia de análisis crítico es más adecuada?', '["Aceptar la versión del medio más conocido, sin verificar más información","Buscar fuentes primarias o independientes que permitan contrastar ambas versiones","Ignorar la noticia por completo, sin ningún análisis adicional","Elegir al azar cuál de las dos versiones creer"]', 1, 'Buscar fuentes primarias o independientes permite contrastar ambas versiones y evaluar cuál es más precisa.', 'avanzada', 120),

  ('Adecuación a contextos comunicativos formales', '¿Qué significa adecuar el discurso oral a un contexto comunicativo formal?', '["Usar un lenguaje coloquial en cualquier situación","Ajustar el vocabulario, el tono y la estructura del discurso según las normas de una situación formal","Evitar completamente el uso de argumentos","Hablar de forma improvisada sin ninguna planificación"]', 1, 'Adecuar el discurso a un contexto formal implica ajustar el vocabulario, el tono y la estructura según las normas de esa situación.', 'inicial', 60),
  ('Adecuación a contextos comunicativos formales', 'Un estudiante debe presentar los resultados de un proyecto ante el consejo escolar del colegio. ¿Qué adecuación comunicativa sería más apropiada?', '["Usar un lenguaje informal, similar al de una conversación entre amigos","Emplear un registro formal, una estructura clara y un vocabulario preciso, adecuados a la instancia","Improvisar el discurso completamente sin ninguna preparación","Ignorar la estructura del discurso y hablar sin ningún orden"]', 1, 'Ante una instancia formal como un consejo escolar, corresponde emplear un registro formal, una estructura clara y un vocabulario preciso.', 'intermedia', 90),
  ('Adecuación a contextos comunicativos formales', '¿Cuál de las siguientes acciones NO corresponde a la adecuación a un contexto comunicativo formal?', '["Usar un registro de lengua formal y preciso","Organizar el discurso con una estructura clara","Utilizar constantemente expresiones coloquiales y modismos","Adecuar el tono a la seriedad de la instancia comunicativa"]', 2, 'Utilizar constantemente expresiones coloquiales y modismos contradice la adecuación a un contexto comunicativo formal.', 'intermedia', 90),
  ('Adecuación a contextos comunicativos formales', 'Un estudiante prepara un mismo contenido para presentarlo en una charla entre compañeros de curso y en una ceremonia formal del colegio. ¿Qué estrategia comunicativa sería más adecuada?', '["Presentar el contenido de exactamente la misma forma en ambos contextos","Adaptar el registro, el tono y la estructura del discurso según las exigencias de cada contexto comunicativo","Usar siempre el registro más formal posible, sin importar el contexto","Usar siempre el registro más informal posible, sin importar el contexto"]', 1, 'Adaptar el registro, el tono y la estructura según cada contexto comunicativo permite comunicar de forma más efectiva y adecuada en ambas situaciones.', 'avanzada', 120)
) as v(short_name, prompt, choices, correct_index, explanation, difficulty, estimated_seconds)
join public.learning_objectives lo
  on lo.short_name = v.short_name
  and lo.unit_id = (
    select id from public.units
    where strand_id = (select id from public.strands where subject_id = (select id from public.subjects where name = 'Lengua Castellana y Comunicación') and name = 'Comunicación Oral')
      and name = 'Comunicación Oral — 2° Medio'
  )
cross join (select id from public.levels where code = 'regular_2_medio') as lv
where lo.level_id = lv.id
  and not exists (
    select 1 from public.questions q2
    where q2.learning_objective_id = lo.id and q2.prompt = v.prompt
  );

-- ============================================================================
-- EJE: INVESTIGACIÓN — 2° MEDIO (4 objetivos x 4 preguntas = 16)
-- ============================================================================
insert into public.questions (
  subject_id, level_id, lesson_id, prompt, choices, correct_index, explanation,
  learning_objective_id, difficulty, question_type, points, estimated_seconds,
  review_status, validation_status, is_active, source_type, generated_by, generated_at
)
select
  (select id from public.subjects where name = 'Lengua Castellana y Comunicación'),
  lv.id, null, v.prompt, v.choices::jsonb, v.correct_index, v.explanation,
  lo.id, v.difficulty, 'seleccion_multiple', 1, v.estimated_seconds,
  'borrador', 'ai_generated_review_required', true, 'validapp_original',
  'claude-sonnet-5 (validapp-assessments)', now()
from (values
  ('Investigación monográfica literaria o social', '¿Qué caracteriza a una investigación monográfica?', '["El estudio profundo y delimitado de un tema específico, literario o social","Un resumen superficial de varios temas sin ninguna profundización","Una opinión personal sin ningún respaldo de fuentes","Un texto narrativo de ficción sobre un tema social"]', 0, 'Una investigación monográfica se caracteriza por el estudio profundo y delimitado de un tema específico, literario o social.', 'inicial', 60),
  ('Investigación monográfica literaria o social', 'Un estudiante desarrolla una investigación monográfica sobre la representación de la mujer en la narrativa chilena del siglo XX, delimitando su análisis a tres autoras específicas. ¿Qué característica de la investigación monográfica cumple esta decisión?', '["La falta de delimitación del tema de estudio","La profundización en un tema específico y delimitado, propia de una monografía","Un enfoque superficial sobre un tema muy amplio","La ausencia de cualquier metodología de análisis"]', 1, 'Delimitar el análisis a tres autoras específicas refleja la profundización en un tema específico, propia de una investigación monográfica.', 'intermedia', 90),
  ('Investigación monográfica literaria o social', '¿Cuál de las siguientes acciones NO corresponde al desarrollo de una investigación monográfica?', '["Delimitar con precisión el tema de estudio","Profundizar en el análisis de fuentes relacionadas con el tema","Abordar de forma superficial múltiples temas sin ninguna relación entre sí","Organizar la información en un desarrollo argumentativo coherente"]', 2, 'Abordar de forma superficial múltiples temas sin relación entre sí contradice el propósito de profundización de una monografía.', 'intermedia', 90),
  ('Investigación monográfica literaria o social', 'Un estudiante investiga sobre el rol del mito en la construcción de la identidad social en una comunidad específica, integrando fuentes literarias y estudios sociales. ¿Qué característica de la investigación monográfica refleja este enfoque?', '["La combinación e integración de distintas fuentes en torno a un tema delimitado y profundizado","Una investigación superficial sin ningún enfoque específico","Una tesis sin ninguna relación con fuentes académicas","Un texto exclusivamente narrativo sin ningún análisis"]', 0, 'Integrar fuentes literarias y sociales en torno a un tema delimitado y profundizado es característico de una investigación monográfica.', 'avanzada', 120),

  ('Jerarquización de fuentes según pertinencia', '¿Qué significa jerarquizar fuentes según su pertinencia en una investigación?', '["Elegir las fuentes al azar sin ningún criterio","Ordenar las fuentes según su relevancia y calidad para responder la pregunta de investigación","Usar únicamente la fuente más extensa disponible","Ignorar cualquier criterio de selección de fuentes"]', 1, 'Jerarquizar fuentes implica ordenarlas según su relevancia y calidad para responder la pregunta de investigación.', 'inicial', 60),
  ('Jerarquización de fuentes según pertinencia', 'Un estudiante encuentra diez fuentes sobre un tema, pero decide priorizar tres que abordan directamente su pregunta de investigación con mayor rigor y actualidad. ¿Qué habilidad está aplicando?', '["Una selección aleatoria de fuentes sin ningún criterio","Una jerarquización de fuentes según su pertinencia y calidad","Una eliminación innecesaria de información relevante","Un uso excesivo de fuentes sin ningún análisis"]', 1, 'Priorizar fuentes según su relación directa con la pregunta de investigación y su rigor es un ejemplo de jerarquización según pertinencia.', 'intermedia', 90),
  ('Jerarquización de fuentes según pertinencia', '¿Cuál de los siguientes criterios NO es relevante para jerarquizar la pertinencia de una fuente?', '["Su relación directa con la pregunta de investigación","El rigor y la actualidad de la información que presenta","La cantidad de páginas que tiene la fuente, sin considerar su contenido","La calidad y el respaldo del autor o institución"]', 2, 'La cantidad de páginas, sin considerar el contenido, no es un criterio relevante para evaluar la pertinencia de una fuente.', 'intermedia', 90),
  ('Jerarquización de fuentes según pertinencia', 'Un estudiante debe elegir entre una fuente extensa pero poco actualizada y otra breve pero con datos recientes y directamente relacionados con su pregunta de investigación. ¿Qué criterio debería priorizar?', '["La extensión de la fuente, sin considerar ningún otro criterio","La pertinencia y actualidad de la información en relación con la pregunta de investigación","Elegir ambas fuentes sin ningún criterio de selección","Descartar ambas fuentes por no ser perfectas"]', 1, 'La pertinencia y actualidad de la información en relación con la pregunta de investigación debe primar por sobre la extensión de la fuente.', 'avanzada', 120),

  ('Citas y referencias bibliográficas', '¿Cuál es el propósito principal de elaborar citas y referencias bibliográficas en un trabajo de investigación?', '["Aumentar artificialmente la extensión del texto","Dar crédito a las fuentes consultadas y permitir que otros verifiquen la información","Hacer el texto más difícil de leer","Evitar tener que desarrollar ideas propias"]', 1, 'Las citas y referencias bibliográficas dan crédito a las fuentes consultadas y permiten que otros verifiquen la información utilizada.', 'inicial', 60),
  ('Citas y referencias bibliográficas', 'Un estudiante incluye al final de su informe una lista con el autor, título, año y editorial de cada fuente consultada. ¿Qué elemento del trabajo de investigación está elaborando?', '["Una introducción al tema","Las referencias bibliográficas del trabajo","La metodología de la investigación","La conclusión del informe"]', 1, 'Una lista con autor, título, año y editorial de cada fuente consultada corresponde a las referencias bibliográficas del trabajo.', 'intermedia', 90),
  ('Citas y referencias bibliográficas', '¿Cuál de las siguientes prácticas NO corresponde a una correcta citación y referencia bibliográfica?', '["Registrar el autor y el título de cada fuente consultada","Seguir un formato consistente para todas las referencias del trabajo","Omitir la referencia de una fuente porque su contenido parece de conocimiento común","Incluir el año de publicación de la fuente cuando esté disponible"]', 2, 'Omitir una referencia asumiendo que el contenido es "de conocimiento común" es una práctica de citación incorrecta y riesgosa.', 'intermedia', 90),
  ('Citas y referencias bibliográficas', 'Un estudiante cita correctamente todas las fuentes textuales que copió, pero olvida referenciar una idea que parafraseó de un autor. ¿Qué debería corregir?', '["Nada, solo se debe citar lo que se copia textualmente","Incluir también la referencia de la idea parafraseada, ya que no es de su propia autoría","Eliminar la idea parafraseada de su trabajo","Citar únicamente las ideas que le parecen más importantes"]', 1, 'Incluso al parafrasear, la idea original no es de la propia autoría del estudiante, por lo que también debe referenciarse.', 'avanzada', 120),

  ('Comunicación clara de conclusiones', '¿Qué característica debe tener la comunicación de las conclusiones de una investigación?', '["Ser confusa y ambigua para generar debate","Ser clara, fundamentada en la evidencia recopilada y bien organizada","Basarse únicamente en la opinión personal del investigador","Repetir textualmente el desarrollo completo de la investigación"]', 1, 'Las conclusiones de una investigación deben comunicarse de forma clara, fundamentada en la evidencia recopilada y bien organizada.', 'inicial', 60),
  ('Comunicación clara de conclusiones', 'Un estudiante presenta las conclusiones de su investigación explicando de forma ordenada qué encontró, qué significa y cómo responde a su pregunta inicial. ¿Qué logra con esta estructura?', '["Confundir a la audiencia con demasiada información","Comunicar de forma clara y organizada los resultados fundamentales de su investigación","Omitir la relación entre la investigación y su pregunta inicial","Repetir la introducción de su informe sin ningún desarrollo"]', 1, 'Explicar de forma ordenada los hallazgos, su significado y su relación con la pregunta inicial permite comunicar conclusiones de forma clara y organizada.', 'intermedia', 90),
  ('Comunicación clara de conclusiones', '¿Cuál de las siguientes formas de comunicar conclusiones NO es adecuada?', '["Explicar de forma clara los principales hallazgos de la investigación","Relacionar las conclusiones con la pregunta de investigación planteada al inicio","Presentar conclusiones que no tienen ninguna relación con la evidencia recopilada","Fundamentar las conclusiones en los datos y fuentes analizados durante la investigación"]', 2, 'Presentar conclusiones sin relación con la evidencia recopilada contradice el propósito de una comunicación de conclusiones fundamentada.', 'intermedia', 90),
  ('Comunicación clara de conclusiones', 'Un estudiante concluye su investigación afirmando algo que sus propios datos no respaldan completamente, exagerando el alcance de sus hallazgos. ¿Qué problema presenta esta forma de comunicar conclusiones?', '["Ninguno, siempre es válido exagerar las conclusiones de una investigación","Las conclusiones no están fundamentadas adecuadamente en la evidencia recopilada","Es una estrategia recomendable para hacer más atractivas las conclusiones","El alcance de una conclusión no necesita relacionarse con los datos obtenidos"]', 1, 'Exagerar el alcance de los hallazgos más allá de lo que los datos respaldan constituye una conclusión no fundamentada adecuadamente en la evidencia.', 'avanzada', 120)
) as v(short_name, prompt, choices, correct_index, explanation, difficulty, estimated_seconds)
join public.learning_objectives lo
  on lo.short_name = v.short_name
  and lo.unit_id = (
    select id from public.units
    where strand_id = (select id from public.strands where subject_id = (select id from public.subjects where name = 'Lengua Castellana y Comunicación') and name = 'Investigación')
      and name = 'Investigación — 2° Medio'
  )
cross join (select id from public.levels where code = 'regular_2_medio') as lv
where lo.level_id = lv.id
  and not exists (
    select 1 from public.questions q2
    where q2.learning_objective_id = lo.id and q2.prompt = v.prompt
  );
